load accidents
population=hwydata(:,14) %Population of states %[output:6e8f2e0a]
traffic_fatalities= hwydata(:,4) %Accidents per state %[output:196d0ac9]
scatter(population,traffic_fatalities) %[output:979f11a1]

% without intercept y=b1*x
b1=population\traffic_fatalities %[output:4722e129]
Predicted_fatalities1=population*b1 %[output:6730aa60]

hold on %[output:979f11a1]
plot(population,Predicted_fatalities1) %[output:979f11a1]
xlabel("Population of state") %[output:979f11a1]
ylabel("Fatal accident per state") %[output:979f11a1]
title('Linear Regression Relation Between Accidents & Population') %[output:979f11a1]
grid on %[output:979f11a1]
%Without y-intercept line starts at (0,0)

%With intercept y=b2*x+b3
%calculate the design matrix
X=[ones(length(population),1),population] %[output:295ede56]
b2=X\traffic_fatalities %[output:7741a30f]
Predicted_fatalities2= X*b2 %[output:675f4ffd]
hold on %[output:979f11a1]
plot(population,Predicted_fatalities2,"--") %[output:979f11a1]
legend("Data","Slope","Slope & Intercept","Location","best") %[output:979f11a1]

